se}],"steps":[{"text":"Hull the strawberries and cut the bananas into chunks.","timer":null},{"text":"Put everything in the blender with the yoghurt, the milk and the honey.","timer":null},{"text":"Blend until completely smooth.","timer":null},{"text":"Serve straight away, nice and cold.","timer":null}],"kids":true,"dessert":true},{"title":"Bowl cake","intro":"The breakfast cake made with oats and banana, cooked in 2 minutes in the microwave.","minutes":5,"calories":300,"difficulty":"Facile","imageSearch":"oatmeal bowl cake","veg":true,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"rolled oat","plural":"rolled oats","qty":160,"unit":"g","have":false},{"name":"banana","plural":"bananas","qty":2,"unit":"","have":false},{"name":"egg","plural":"eggs","qty":4,"unit":"","have":false},{"name":"milk","plural":"milk","qty":20,"unit":"cl","have":false},{"name":"baking powder","plural":"baking powder","qty":1,"unit":"tsp","have":false}],"steps":[{"text":"Mash the bananas in 4 bowls.","timer":null},{"text":"Add 40 g of oats, 1 egg, 5 cl of milk and a pinch of baking powder to each bowl.","timer":null},{"text":"Mix well.","timer":null},{"text":"Cook each bowl for 2 minutes in the microwave.","timer":{"label":"Microwave","min":2}}],"dessert":true},{"title":"Fresh fruit salad","intro":"Chopped seasonal fruit with a light lemon syrup.","minutes":20,"calories":150,"difficulty":"Facile","imageSearch":"fresh fruit salad","veg":true,"oven":false,"cold":true,"missing":"","origin":"","serves":4,"items":[{"name":"apple","plural":"apples","qty":2,"unit":"","have":false},{"name":"pear","plural":"pears","qty":2,"unit":"","have":false},{"name":"banana","plural":"bananas","qty":2,"unit":"","have":false},{"name":"orange","plural":"oranges","qty":2,"unit":"","have":false},{"name":"grape","plural":"grapes","qty":200,"unit":"g","have":false},{"name":"lemon","plural":"lemons","qty":1,"unit":"","have":false},{"name":"sugar","plural":"sugar","qty":2,"unit":"tbsp","hav