":"blueberry","plural":"blueberries","qty":100,"unit":"g","have":false}],"steps":[{"text":"Blitz the porridge oats with the banana, eggs, milk and baking powder.","timer":null},{"text":"Add the blueberries.","timer":null},{"text":"Cook for 2 min on each side in a non-stick pan.","timer":{"label":"Pan","min":4}}],"kids":true,"dessert":true,"makes":{"n":10,"one":"pancake","many":"pancakes"}},{"title":"Banana ice cream","intro":"A quick, light banana ice cream.","minutes":5,"calories":120,"difficulty":"Facile","imageSearch":"banana nice cream","veg":true,"oven":false,"cold":true,"missing":"","origin":"","serves":4,"items":[{"name":"frozen banana","plural":"frozen bananas","qty":4,"unit":"","have":false},{"name":"cocoa powder","plural":"cocoa powder","qty":1,"unit":"tbsp","have":false}],"steps":[{"text":"Slice the bananas before freezing them.","timer":null},{"text":"Blend them until they have an ice cream texture.","timer":null},{"text":"Add the cocoa if you like.","timer":null},{"text":"Serve straight away.","timer":null}],"kids":true,"dessert":true},{"title":"Chocolate bowl cake","intro":"A bowl cake with a gooey chocolate centre.","minutes":5,"calories":350,"difficulty":"Facile","imageSearch":"chocolate bowl cake","veg":true,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"rolled oat","plural":"rolled oats","qty":160,"unit":"g","have":false},{"name":"banana","plural":"bananas","qty":2,"unit":"","have":false},{"name":"egg","plural":"eggs","qty":4,"unit":"","have":false},{"name":"milk","plural":"milk","qty":20,"unit":"cl","have":false},{"name":"cocoa powder","plural":"cocoa powder","qty":2,"unit":"tbsp","have":false},{"name":"dark chocolate","plural":"dark chocolate","qty":40,"unit":"g","have":false}],"steps":[{"text":"Mash the bananas in 4 bowls and add the oats, the eggs, the milk and the cocoa.","timer":null},{"text":"Mix well.","timer":null},{"text":"Push a square of chocolate into the middle of each bowl.","timer":null},{"text":"Coo