, then the chia seeds.","timer":null},{"text":"Stir again after 10 minutes.","timer":null},{"text":"Leave to set for at least 4 hours in the fridge.","timer":null},{"text":"Serve with the sliced banana.","timer":null}],"dessert":true},{"title":"Banana brownies","intro":"A soft, no-waste brownie made with very ripe bananas.","minutes":35,"calories":330,"difficulty":"Facile","imageSearch":"banana brownie","veg":true,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"dark chocolate","plural":"dark chocolate","qty":150,"unit":"g","have":false},{"name":"banana","plural":"bananas","qty":2,"unit":"","have":false},{"name":"butter","plural":"butter","qty":60,"unit":"g","have":false},{"name":"brown sugar","plural":"brown sugar","qty":60,"unit":"g","have":false},{"name":"egg","plural":"eggs","qty":2,"unit":"","have":false},{"name":"flour","plural":"flour","qty":60,"unit":"g","have":false}],"steps":[{"text":"Preheat the oven to 180 °C.","timer":null},{"text":"Melt the chocolate with the butter.","timer":null},{"text":"Mash the bananas and mix with the eggs, sugar, chocolate and flour.","timer":null},{"text":"Bake for 22 min.","timer":{"label":"Oven","min":22}}],"kids":true,"dessert":true},{"title":"Chocolate chip banana bread","intro":"The indulgent banana bread, full of melting chocolate chips.","minutes":70,"calories":340,"difficulty":"Facile","imageSearch":"chocolate chip banana bread","veg":true,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"banana","plural":"bananas","qty":3,"unit":"","have":false},{"name":"egg","plural":"eggs","qty":2,"unit":"","have":false},{"name":"brown sugar","plural":"brown sugar","qty":90,"unit":"g","have":false},{"name":"melted butter","plural":"melted butter","qty":80,"unit":"g","have":false},{"name":"flour","plural":"flour","qty":220,"unit":"g","have":false},{"name":"baking powder","plural":"baking powder","qty":2,"unit":"tsp","have":false},{"name":"chocolate chip","plural":"chocolate chips","qty":100,"unit":"g","have":false}],"steps":[{"text":"Preheat the oven to 180 °C.","timer":null},{"text":"Mash the bananas and mix them with the eggs, sugar and melted butter.","timer":null},{"text":"Add the flour and baking powder, then the chocolate chips.","timer":null},{"text":"Pour into a loaf tin and bake for 50 min.","timer":{"label":"Oven","min":50}}],"kids":true,"dessert":true},{"title":"Smoothie bowl","intro":"The smoothie you eat with a spoon, topped with fruit and granola.","minutes":10,"calories":320,"difficulty":"Facile","imageSearch":"acai smoothie bowl","veg":true,"oven":false,"cold":true,"missing":"","origin":"","serves":4,"items":[{"name":"frozen banana","plural":"frozen bananas","qty":2,"unit":"","have":false},{"name":"frozen mixed berries","plural":"frozen mixed berries","qty":300,"unit":"g","have":false},{"name":"greek yoghurt","plural":"greek yoghurts","qty":2,"unit":"","have":false},{"name":"granola","plural":"granola","qty":60,"unit":"g","have":false},{"name":"kiwi","plural":"kiwis","qty":1,"unit":"","have":false}],"steps":[{"text":"Blend the frozen bananas, the berries and the yoghurt with no liquid, for a thick texture.","timer":null},{"text":"Pour into bowls.","timer":null},{"text":"Top with granola and sliced kiwi.","timer":null},{"text":"Serve right away.","timer":null}],"dessert":true},{"title":"Green smoothie","intro":"A fresh, vitamin-packed smoothie, all green.","minutes":5,"calories":140,"difficulty":"Facile","imageSearch":"green smoothie","veg":true,"oven":false,"cold":true,"missing":"","origin":"","serves":4,"items":[{"name":"baby spinach","plural":"baby spinach","qty":60,"unit":"g","have":false},{"name":"kiwi","plural":"kiwis","qty":2,"unit":"","have":false},{"name":"apple","plural":"apples","qty":1,"unit":"","have":false},{"name":"banana","plural":"bananas","qty":1,"unit":"","have":false},{"name":"orange juice","plural":"orange juice","qty":30,"unit":"cl","have":false}],"steps":[{"text":"Peel the kiwis and the banana, and c