insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('en:citron', 'lemon', array['en:lemon']::text[], 'list', $r$[{"title":"Pan-seared scallops","intro":"Scallops seared in butter, golden outside and pearly inside.","minutes":15,"calories":250,"difficulty":"Moyen","imageSearch":"seared scallops","veg":false,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"scallop","plural":"scallops","qty":16,"unit":"","have":false},{"name":"butter","plural":"butter","qty":30,"unit":"g","have":false},{"name":"lemon","plural":"lemons","qty":1,"unit":"","have":false},{"name":"parsley","plural":"parsley","qty":null,"unit":"","have":false},{"name":"salt","plural":"salt","qty":null,"unit":"","have":false}],"steps":[{"text":"Dry the scallops well on kitchen paper.","timer":null},{"text":"Heat the butter until it foams.","timer":null},{"text":"Sear the scallops for 1 min 30 on each side without moving them.","timer":{"label":"Pan","min":3}},{"text":"Squeeze over the lemon juice, add salt and sprinkle with parsley.","timer":null}]},{"title":"Madeleines","intro":"Little golden madeleines with their characteristic bump, flavoured with butter and lemon.","minutes":80,"calories":110,"difficulty":"Facile","imageSearch":"french madeleines","veg":true,"oven":true,"cold":false,"missing":"","origin":"Speciality of Lorraine","serves":4,"items":[{"name":"flour","plural":"flour","qty":150,"unit":"g","have":false},{"name":"egg","plural":"eggs","qty":3,"unit":"","have":false},{"name":"sugar","plural":"sugar","qty":130,"unit":"g","have":false},{"name":"melted butter","plural":"melted butter","qty":120,"unit":"g","have":false},{"name":"baking powder","plural":"baking powder","qty":1,"unit":"tsp","have":false},{"name":"lemon","plural":"lemons","qty":1,"unit":"","have":false},{"name":"salt","plural":"salt","qty":null,"unit":"","have":false}],"steps":[{"text":"Whisk the eggs and sugar until the mixture turns pale.","timer":null},{"text":"Add the lemon zest, flour, baking powder and a pinch of salt, then the melted butter.","timer":null},{"text":"Chill the batter for 1 h. This is the secret of the bump.","timer":{"label":"Rest","min":60}},{"text":"Preheat the oven to 220 °C. Fill the buttered moulds three-quarters full.","timer":null},{"text":"Bake for 5 min, turn the oven down to 180 °C and bake for another 5 min.","timer":{"label":"Oven","min":10}}],"kids":true,"dessert":true,"makes":{"n":24,"one":"madeleine","many":"madeleines"}},{"title":"Marinated chicken skewers","intro":"Chicken skewers marinated in lemon and paprika, with peppers and onions.","minutes":45,"calories":350,"difficulty":"Facile","imageSearch":"grilled chicken skewers","veg":false,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"chicken breast","plural":"chicken breasts","qty":4,"unit":"","have":false},{"name":"red pepper","plural":"red peppers","qty":1,"unit":"","have":false},{"name":"red onion","plural":"red onions","qty":1,"unit":"","have":false},{"name":"lemon","plural":"lemons","qty":1,"unit":"","have":false},{"name":"paprika","plural":"paprika","qty":2,"unit":"tsp","have":false},{"name":"olive oil","plural":"olive oil","qty":3,"unit":"tbsp","have":false},{"name":"garlic","plural":"garlic","qty":1,"unit":"clove","have":false}],"steps":[{"text":"Cut the chicken into cubes and marinate it for 20 min with the oil, the lemon, the paprika and the garlic.","timer":{"label":"Rest","min":20}},{"text":"Cut the pepper and the onion into chunks.","timer":null},{"text":"Thread the chicken and the vegetables onto skewers, alternating them.","timer":null},{"text":"Grill them for 12 min, turning them.","timer":{"label":"Pan","min":12}}],"kids":true,"makes":{"n":8,"one":"skewer","many":"skewers"}},{"title":"Tzatziki","intro":"Greek yoghurt with cucumber, garlic and dill, for nibbles or grilled meat.","minutes":15,"calories":110,"difficulty":"Facile","imageSearch":"tzatziki","veg":true,"oven":false,"cold":true,"missing