insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('en:fraise', 'strawberry', array['en:strawberry']::text[], 'list', $r$[{"title":"Banana and strawberry smoothie","intro":"A smooth banana and strawberry smoothie, made with yoghurt.","minutes":5,"calories":180,"difficulty":"Facile","imageSearch":"strawberry banana smoothie","veg":true,"oven":false,"cold":true,"missing":"","origin":"","serves":4,"items":[{"name":"banana","plural":"bananas","qty":2,"unit":"","have":false},{"name":"strawberry","plural":"strawberries","qty":300,"unit":"g","have":false},{"name":"plain yoghurt","plural":"plain yoghurts","qty":2,"unit":"","have":false},{"name":"milk","plural":"milk","qty":30,"unit":"cl","have":false},{"name":"honey","plural":"honey","qty":1,"unit":"tbsp","have":false}],"steps":[{"text":"Hull the strawberries and cut the bananas into chunks.","timer":null},{"text":"Put everything in the blender with the yoghurt, the milk and the honey.","timer":null},{"text":"Blend until completely smooth.","timer":null},{"text":"Serve straight away, nice and cold.","timer":null}],"kids":true,"dessert":true},{"title":"Strawberry charlotte","intro":"Sponge fingers around a light strawberry mousse.","minutes":40,"calories":350,"difficulty":"Moyen","imageSearch":"strawberry charlotte","veg":true,"oven":false,"cold":true,"missing":"","origin":"","serves":4,"items":[{"name":"sponge finger","plural":"sponge fingers","qty":24,"unit":"","have":false},{"name":"strawberry","plural":"strawberries","qty":500,"unit":"g","have":false},{"name":"whole liquid cream","plural":"whole liquid cream","qty":30,"unit":"cl","have":false},{"name":"fromage blanc","plural":"fromage blanc","qty":250,"unit":"g","have":false},{"name":"sugar","plural":"sugar","qty":80,"unit":"g","have":false},{"name":"gelatine","plural":"gelatine","qty":4,"unit":"leaves","have":false}],"steps":[{"text":"Soften the gelatine in cold water. Blend half the strawberries with the sugar.","timer":null},{"text"