insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('en:poire', 'pear', array['en:pear']::text[], 'list', $r$[{"title":"Tarte Bourdaloue","intro":"A pear tart on a golden almond cream.","minutes":60,"calories":420,"difficulty":"Moyen","imageSearch":"pear almond tart","veg":true,"oven":true,"cold":false,"missing":"","origin":"French pastry","serves":4,"items":[{"name":"shortcrust pastry","plural":"shortcrust pastry","qty":1,"unit":"","have":false},{"name":"pear in syrup","plural":"pears in syrup","qty":8,"unit":"","have":false},{"name":"ground almond","plural":"ground almonds","qty":100,"unit":"g","have":false},{"name":"soft butter","plural":"soft butter","qty":80,"unit":"g","have":false},{"name":"sugar","plural":"sugar","qty":80,"unit":"g","have":false},{"name":"egg","plural":"eggs","qty":2,"unit":"","have":false},{"name":"flaked almond","plural":"flaked almonds","qty":20,"unit":"g","have":false}],"steps":[{"text":"Preheat the oven to 180 °C and line a tin with the pastry.","timer":null},{"text":"Mix the soft butter, the sugar, the ground almonds and the eggs.","timer":null},{"text":"Spread this cream over the pastry.","timer":null},{"text":"Slice the drained pear halves and arrange them in a rosette.","timer":null},{"text":"Sprinkle with flaked almonds and bake for 35 min.","timer":{"label":"Oven","min":35}}],"dessert":true},{"title":"Beef bulgogi","intro":"Sweet and salty marinated Korean beef, seared and served with rice.","minutes":40,"calories":480,"difficulty":"Facile","imageSearch":"beef bulgogi","veg":false,"oven":false,"cold":false,"missing":"","origin":"Korean recipe","serves":4,"items":[{"name":"thinly sliced beef","plural":"thinly sliced beef","qty":500,"unit":"g","have":false},{"name":"soy sauce","plural":"soy sauce","qty":5,"unit":"tbsp","have":false},{"name":"brown sugar","plural":"brown sugar","qty":2,"unit":"tbsp","have":false},{"name":"pear","plural":"pears","qty":1,"unit":"","have":false},{"name":"garlic","plural":"garlic","qty":3,"unit":"clove","have":false},{"name":"sesame oil","plural":"sesame oil","qty":1,"unit":"tbsp","have":false},{"name":"spring onion","plural":"spring onions","qty":3,"unit":"","have":false},{"name":"rice","plural":"rice","qty":250,"unit":"g","have":false}],"steps":[{"text":"Grate the pear and mix it with the soy sauce, the sugar, the garlic and the sesame oil.","timer":null},{"text":"Cut the beef into thin slices and marinate for 20 minutes.","timer":{"label":"Rest","min":20}},{"text":"Cook the rice.","timer":{"label":"Cooking","min":12}},{"text":"Sear the beef for 3 minutes over a very high heat.","timer":{"label":"Pan","min":3}},{"text":"Sprinkle with spring onion and serve with the rice.","timer":null}]},{"title":"Fresh fruit salad","intro":"Chopped seasonal fruit with a light lemon syrup.","minutes":20,"calories":150,"difficulty":"Facile","imageSearch":"fresh fruit salad","veg":true,"oven":false,"cold":true,"missing":"","origin":"","serves":4,"items":[{"name":"apple","plural":"apples","qty":2,"unit":"","have":false},{"name":"pear","plural":"pears","qty":2,"unit":"","have":false},{"name":"banana","plural":"bananas","qty":2,"unit":"","have":false},{"name":"orange","plural":"oranges","qty":2,"unit":"","have":false},{"name":"grape","plural":"grapes","qty":200,"unit":"g","have":false},{"name":"lemon","plural":"lemons","qty":1,"unit":"","have":false},{"name":"sugar","plural":"sugar","qty":2,"unit":"tbsp","have":false}],"steps":[{"text":"Squeeze the lemon and mix the juice with the sugar.","timer":null},{"text":"Peel the oranges, removing all the pith, and cut into pieces.","timer":null},{"text":"Dice the apples, pears and bananas.","timer":null},{"text":"Mix all the fruit with the grapes and the sweet juice.","timer":null},{"text":"Chill for 30 min before serving.","timer":null}],"kids":true,"dessert":true},{"title":"Pears belle Hélène","intro":"Pears poached in vanilla syrup, covered with hot chocolate.","minutes":40,"calories":330,"difficulty":"Facile","imageSearch":"poire belle helene","veg":true,"oven":false,"cold":true,"missing":"","origin":"French dessert","serves":4,"items":[{"name":"pear","plural":"pears","qty":4,"unit":"","have":false},{"name":"sugar","plural":"sugar","qty":150,"unit":"g","have":false},{"name":"vanilla pod","plural":"vanilla pods","qty":1,"unit":"","have":false},{"name":"dark chocolate","plural":"dark chocolate","qty":150,"unit":"g","have":false},{"name":"liquid cream","plural":"liquid cream","qty":15,"unit":"cl","have":false},{"name":"vanilla ice cream","plural":"vanilla ice cream","qty":50,"unit":"cl","have":false}],"steps":[{"text":"Bring 1 litre of water to the boil with the sugar and the split vanilla pod.","timer":null},{"text":"Peel the pears, leaving the stalk on, and poach them in the syrup for 20 min.","timer":{"label":"Cooking","min":20}},{"text":"Leave them to cool in the syrup.","timer":null},{"text":"Melt the chocolate in the hot cream.","timer":null},{"text":"Serve each pear with a scoop of ice cream and the chocolate sauce.","timer":null}],"dessert":true},{"title":"Apple and pear compote","intro":"A gentle compote, sweetened only by the fruit.","minutes":30,"calories":100,"difficulty":"Facile","imageSearch":"apple pear compote","veg":true,"oven":false,"cold":true,"missing":"","origin":"","serves":4,"items":[{"name":"apple","plural":"apples","qty":4,"unit":"","have":false},{"name":"pear","plural":"pears","qty":4,"unit":"","have":false},{"name":"cinnamon","plural":"cinnamon","qty":1,"unit":"tsp","have":false}],"steps":[{"text":"Peel and core the fruit and cut into pieces.","timer":null},{"text":"Put it in a pan with 5 cl of water and the cinnamon.","timer":null},{"text":"Cook for 20 min with the lid on.","timer":{"label":"Cooking","min":20}},{"text":"Mash or blend, then leave to cool.","timer":null}],"kids":true,"dessert":true},{"title":"Pears poached in red wine","intro":"Red, fragrant pears for a winter dessert.","minutes":50,"calories":250,"difficulty":"Facile","imageSearch":"poached pears red wine","veg":true,"oven":false,"cold":true,"missing":"","origin":"","serves":4,"items":[{"name":"pear","plural":"pears","qty":4,"unit":"","have":false},{"name":"red wine","plural":"red wine","qty":75,"unit":"cl","have":false},{"name":"sugar","plural":"sugar","qty":120,"unit":"g","have":false},{"name":"cinnamon stick","plural":"cinnamon sticks","qty":1,"unit":"","have":false},{"name":"orange","plural":"oranges","qty":1,"unit":"","have":false}],"steps":[{"text":"Bring the wine to the boil with the sugar, cinnamon and orange zest.","timer":null},{"text":"Peel the pears, leaving the stalk on.","timer":null},{"text":"Poach them for 30 min in the simmering wine, turning them over.","timer":{"label":"Cooking","min":30}},{"text":"Remove the pears and boil the wine down to a syrup.","timer":{"label":"Cooking","min":10}},{"text":"Serve warm or cold, covered with syrup.","timer":null}],"dessert":true},{"title":"Healthy oat crumble","intro":"A crunchy, lighter crumble made with porridge oats.","minutes":45,"calories":260,"difficulty":"Facile","imageSearch":"oat crumble healthy","veg":true,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"apple","plural":"apples","qty":4,"unit":"","have":false},{"name":"pear","plural":"pears","qty":2,"unit":"","have":false},{"name":"porridge oat","plural":"porridge oats","qty":80,"unit":"g","have":false},{"name":"ground almonds","plural":"ground almonds","qty":40,"unit":"g","have":false},{"name":"butter","plural":"butter","qty":50,"unit":"g","have":false},{"name":"honey","plural":"honey","qty":2,"unit":"tbsp","have":false},{"name":"cinnamon","plural":"cinnamon","qty":1,"unit":"tsp","have":false}],"steps":[{"text":"Preheat the oven to 180 °C.","timer":null},{"text":"Put the chopped fruit in a dish with the cinnamon.","timer":null},{"text":"Mix the oats, ground almonds, melted butter and honey, and spread over the fruit.","timer":null},{"text":"Bake for 30 min.","timer":{"label":"Oven","min":30}}],"dessert":true},{"title":"Chocolate and pear galette des rois","intro":"The chocolate and pear duo, in a galette des rois.","minutes":60,"calories":520,"difficulty":"Moyen","imageSearch":"chocolate pear galette","veg":true,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"puff pastry","plural":"puff pastries","qty":2,"unit":"","have":false},{"name":"ground almond","plural":"ground almonds","qty":100,"unit":"g","have":false},{"name":"sugar","plural":"sugar","qty":80,"unit":"g","have":false},{"name":"soft butter","plural":"soft butter","qty":80,"unit":"g","have":false},{"name":"egg","plural":"eggs","qty":3,"unit":"","have":false},{"name":"dark chocolate","plural":"dark chocolate","qty":80,"unit":"g","have":false},{"name":"pear","plural":"pears","qty":2,"unit":"","have":false}],"steps":[{"text":"Preheat the oven to 200 °C. Melt the chocolate.","timer":null},{"text":"Mix the ground almonds, sugar, butter, 2 eggs and the melted chocolate.","timer":null},{"text":"Roll out one pastry, spread with frangipane and diced pears, and place the charm.","timer":null},{"text":"Cover with the second pastry, seal the edges and brush with the last egg.","timer":null},{"text":"Bake for 30 min.","timer":{"label":"Oven","min":30}}],"dessert":true},{"title":"Thin pear tart","intro":"A thin, crisp tart with fresh pears.","minutes":40,"calories":280,"difficulty":"Facile","imageSearch":"thin pear tart","veg":true,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"puff pastry","plural":"puff pastry","qty":1,"unit":"","have":false},{"name":"pear","plural":"pears","qty":4,"unit":"","have":false},{"name":"sugar","plural":"sugar","qty":30,"unit":"g","have":false},{"name":"butter","plural":"butter","qty":20,"unit":"g","have":false},{"name":"cinnamon","plural":"cinnamon","qty":1,"unit":"tsp","have":false}],"steps":[{"text":"Preheat the oven to 200 °C. Roll the pastry out onto a tray.","timer":null},{"text":"Peel the pears and slice them thinly.","timer":null},{"text":"Arrange them on the pastry, sprinkle with sugar and cinnamon, and dot with butter.","timer":null},{"text":"Bake for 25 min.","timer":{"label":"Oven","min":25}}],"dessert":true},{"title":"Pear and chocolate tart","intro":"Pear and chocolate together in a rich tart.","minutes":60,"calories":470,"difficulty":"Moyen","imageSearch":"pear chocolate tart","veg":true,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"shortcrust pastry","plural":"shortcrust pastry","qty":1,"unit":"","have":false},{"name":"pear in syrup","plural":"pears in syrup","qty":8,"unit":"","have":false},{"name":"ground almond","plural":"ground almonds","qty":80,"unit":"g","have":false},{"name":"dark chocolate","plural":"dark chocolate","qty":100,"unit":"g","have":false},{"name":"butter","plural":"butter","qty":60,"unit":"g","have":false},{"name":"sugar","plural":"sugar","qty":60,"unit":"g","have":false},{"name":"egg","plural":"eggs","qty":2,"unit":"","have":false}],"steps":[{"text":"Preheat the oven to 180 °C and line a tin with the pastry.","timer":null},{"text":"Melt the chocolate with the butter and mix with the sugar, the eggs and the ground almonds.","timer":null},{"text":"Spread over the pastry and lay the sliced pears on top.","timer":null},{"text":"Bake for 35 min.","timer":{"label":"Oven","min":35}}],"dessert":true},{"title":"Honey roast pears","intro":"Soft pears caramelised with honey.","minutes":35,"calories":180,"difficulty":"Facile","imageSearch":"roasted pears honey","veg":true,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"pear","plural":"pears","qty":4,"unit":"","have":false},{"name":"honey","plural":"honey","qty":3,"unit":"tbsp","have":false},{"name":"butter","plural":"butter","qty":20,"unit":"g","have":false},{"name":"cinnamon","plural":"cinnamon","qty":1,"unit":"tsp","have":false}],"steps":[{"text":"Preheat the oven to 200 °C.","timer":null},{"text":"Cut the pears in half and remove the cores.","timer":null},{"text":"Put them in a dish, drizzle with honey and dot with butter and cinnamon.","timer":null},{"text":"Bake for 25 min, basting halfway through.","timer":{"label":"Oven","min":25}}],"kids":true,"dessert":true},{"title":"Pear tarte tatin","intro":"The tatin with a twist, made with caramelised pears.","minutes":60,"calories":370,"difficulty":"Moyen","imageSearch":"pear tarte tatin","veg":true,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"puff pastry","plural":"puff pastries","qty":1,"unit":"","have":false},{"name":"pear","plural":"pears","qty":6,"unit":"","have":false},{"name":"sugar","plural":"sugar","qty":100,"unit":"g","have":false},{"name":"butter","plural":"butter","qty":50,"unit":"g","have":false}],"steps":[{"text":"Preheat the oven to 190 °C.","timer":null},{"text":"Make a caramel with the sugar, then add the butter.","timer":{"label":"Caramel","min":6}},{"text":"Arrange the pear wedges in the caramel and cover with the pastry.","timer":null},{"text":"Bake for 30 min, then turn out.","timer":{"label":"Oven","min":30}}],"dessert":true}]$r$::jsonb, 'claude')
