insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('en:noi de coco', 'coconut', array['en:coconut']::text[], 'list', $r$[{"title":"Homemade granola","intro":"Oats, nuts and honey roasted in the oven into crunchy clusters.","minutes":40,"calories":250,"difficulty":"Facile","imageSearch":"homemade granola","veg":true,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"rolled oat","plural":"rolled oats","qty":300,"unit":"g","have":false},{"name":"almond","plural":"almonds","qty":80,"unit":"g","have":false},{"name":"hazelnut","plural":"hazelnuts","qty":50,"unit":"g","have":false},{"name":"honey","plural":"honey","qty":5,"unit":"tbsp","have":false},{"name":"coconut oil","plural":"coconut oil","qty":4,"unit":"tbsp","have":false},{"name":"cinnamon","plural":"cinnamon","qty":1,"unit":"tsp","have":false}],"steps":[{"text":"Preheat the oven to 160 °C.","timer":null},{"text":"Mix the oats, the almonds, the crushed hazelnuts and the cinnamon.","timer":null},{"text":"Add the honey and the melted oil and mix well.","timer":null},{"text":"Spread on a baking tray and bake for 25 minutes, stirring every 10 minutes.","timer":{"label":"Oven","min":25}},{"text":"Leave to cool before putting in a jar.","timer":null}],"dessert":true},{"title":"Coconut and dried fruit granola","intro":"A tropical granola with coconut and dried apricots.","minutes":40,"calories":260,"difficulty":"Facile","imageSearch":"coconut granola","veg":true,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"rolled oat","plural":"rolled oats","qty":300,"unit":"g","have":false},{"name":"desiccated coconut","plural":"desiccated coconut","qty":50,"unit":"g","have":false},{"name":"almond","plural":"almonds","qty":60,"unit":"g","have":false},{"name":"dried apricot","plural":"dried apricots","qty":80,"unit":"g","have":false},{"name":"maple syrup","plural":"maple syrup","qty":5,"unit":"tbsp","have":false},{"name":"coconut oil","plural":"coconut oil","qty":3,"unit":"tbsp","have":false}],"steps":[{"text":"Preheat the oven to 160 °C.","timer":null},{"text":"Mix the oats, the coconut and the almonds, then the maple syrup and the melted oil.","timer":null},{"text":"Spread on a baking tray and bake for 25 minutes, stirring.","timer":{"label":"Oven","min":25}},{"text":"Leave to cool and add the chopped apricots.","timer":null}],"dessert":true},{"title":"Chocolate granola","intro":"A chocolatey granola for those with a sweet tooth.","minutes":40,"calories":280,"difficulty":"Facile","imageSearch":"chocolate granola","veg":true,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"rolled oat","plural":"rolled oats","qty":300,"unit":"g","have":false},{"name":"hazelnut","plural":"hazelnuts","qty":80,"unit":"g","have":false},{"name":"cocoa powder","plural":"cocoa powder","qty":3,"unit":"tbsp","have":false},{"name":"honey","plural":"honey","qty":5,"unit":"tbsp","have":false},{"name":"coconut oil","plural":"coconut oil","qty":4,"unit":"tbsp","have":false},{"name":"chocolate chip","plural":"chocolate chips","qty":60,"unit":"g","have":false}],"steps":[{"text":"Preheat the oven to 160 °C.","timer":null},{"text":"Mix the oats, the crushed hazelnuts and the cocoa, then the honey and the melted oil.","timer":null},{"text":"Spread on a baking tray and bake for 25 minutes, stirring.","timer":{"label":"Oven","min":25}},{"text":"Leave to cool and add the chocolate chips.","timer":null}],"kids":true,"dessert":true},{"title":"Coconut flan","intro":"A coconut flan, like in the French Caribbean.","minutes":60,"calories":360,"difficulty":"Facile","imageSearch":"coconut flan","veg":true,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"milk","plural":"milk","qty":50,"unit":"cl","have":false},{"name":"coconut milk","plural":"coconut milk","qty":25,"unit":"cl","have":false},{"name":"egg","plural":"eggs","qty":3,"unit":"","have":false},{"name":"sugar","plural":"sugar","qty":120,"unit":"g","have":false},{"name":"desiccated coconut","plural":"desiccated coconut","qty":60,"unit":"g","have":false},{"name":"cornflour","plural":"cornflour","qty":60,"unit":"g","have":false}],"steps":[{"text":"Preheat the oven to 180 °C.","timer":null},{"text":"Heat the milks, add the eggs beaten with the sugar and cornflour, and thicken.","timer":{"label":"Custard","min":4}},{"text":"Add the coconut, pour into a dish and bake for 40 min.","timer":{"label":"Oven","min":40}}],"dessert":true},{"title":"Lime and coconut mousse","intro":"A tropical mousse with lime and coconut.","minutes":20,"calories":260,"difficulty":"Facile","imageSearch":"lime coconut mousse","veg":true,"oven":false,"cold":true,"missing":"","origin":"","serves":4,"items":[{"name":"lime","plural":"limes","qty":3,"unit":"","have":false},{"name":"coconut cream","plural":"coconut cream","qty":20,"unit":"cl","have":false},{"name":"sweetened condensed milk","plural":"sweetened condensed milk","qty":200,"unit":"g","have":false},{"name":"double cream","plural":"double cream","qty":15,"unit":"cl","have":false}],"steps":[{"text":"Mix the condensed milk with the juice and zest of the limes.","timer":null},{"text":"Whip the double cream and coconut cream together, both well chilled.","timer":null},{"text":"Gently fold into the lime mixture.","timer":null},{"text":"Spoon into glasses and chill for 3 h.","timer":null}],"dessert":true},{"title":"No added sugar banana bread","intro":"A soft, light cake sweetened only by the fruit.","minutes":70,"calories":210,"difficulty":"Facile","imageSearch":"healthy banana bread oats","veg":true,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"banana","plural":"bananas","qty":4,"unit":"","have":false},{"name":"egg","plural":"eggs","qty":2,"unit":"","have":false},{"name":"coconut oil","plural":"coconut oil","qty":4,"unit":"tbsp","have":false},{"name":"wholemeal flour","plural":"wholemeal flour","qty":150,"unit":"g","have":false},{"name":"rolled oats","plural":"rolled oats","qty":60,"unit":"g","have":false},{"name":"baking powder","plural":"baking powder","qty":2,"unit":"tsp","have":false},{"name":"cinnamon","plural":"cinnamon","qty":1,"unit":"tsp","have":false}],"steps":[{"text":"Preheat the oven to 180 °C.","timer":null},{"text":"Mash the bananas and mix them with the eggs and melted oil.","timer":null},{"text":"Add the flour, oats, baking powder and cinnamon.","timer":null},{"text":"Pour into a loaf tin and bake for 45 min.","timer":{"label":"Oven","min":45}}],"kids":true,"dessert":true},{"title":"Honey roasted chickpeas","intro":"Sweet, crunchy chickpeas for a snack.","minutes":40,"calories":200,"difficulty":"Facile","imageSearch":"honey roasted chickpeas","veg":true,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"chickpea","plural":"chickpeas","qty":400,"unit":"g","have":false},{"name":"coconut oil","plural":"coconut oil","qty":1,"unit":"tbsp","have":false},{"name":"honey","plural":"honey","qty":2,"unit":"tbsp","have":false},{"name":"cinnamon","plural":"cinnamon","qty":1,"unit":"tsp","have":false}],"steps":[{"text":"Preheat the oven to 200 °C.","timer":null},{"text":"Dry the chickpeas and bake them for 20 min with the oil.","timer":{"label":"Oven","min":20}},{"text":"Mix them with the honey and the cinnamon.","timer":null},{"text":"Put them back in the oven for 10 min.","timer":{"label":"Oven","min":10}}],"dessert":true}]$r$::jsonb, 'claude')
