insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('en:creme', 'cream', array['en:cream']::text[], 'list', $r$[{"title":"Crème brûlée","intro":"A silky vanilla custard under a thin layer of caramelised sugar.","minutes":70,"calories":380,"difficulty":"Moyen","imageSearch":"creme brulee","veg":true,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"double cream","plural":"double cream","qty":50,"unit":"cl","have":false},{"name":"egg yolk","plural":"egg yolks","qty":5,"unit":"","have":false},{"name":"sugar","plural":"sugar","qty":80,"unit":"g","have":false},{"name":"vanilla pod","plural":"vanilla pods","qty":1,"unit":"","have":false},{"name":"brown sugar","plural":"brown sugar","qty":4,"unit":"tbsp","have":false}],"steps":[{"text":"Preheat the oven to 100 °C.","timer":null},{"text":"Heat the cream with the split vanilla pod.","timer":null},{"text":"Whisk the yolks and sugar, then pour in the hot cream, stirring.","timer":null},{"text":"Divide between ramekins and bake for 1 h.","timer":{"label":"Oven","min":60}},{"text":"Leave to cool in the fridge for 3 h, sprinkle with brown sugar and caramelise with a blowtorch or under the grill.","timer":{"label":"Chill","min":180}}],"dessert":true},{"title":"Chocolate yule log","intro":"A rolled sponge filled and covered with chocolate ganache, for Christmas dinner.","minutes":70,"calories":420,"difficulty":"Difficile","imageSearch":"chocolate yule log","veg":true,"oven":true,"cold":false,"missing":"","origin":"Christmas tradition","serves":4,"items":[{"name":"egg","plural":"eggs","qty":4,"unit":"","have":false},{"name":"sugar","plural":"sugar","qty":100,"unit":"g","have":false},{"name":"flour","plural":"flour","qty":100,"unit":"g","have":false},{"name":"dark chocolate","plural":"dark chocolate","qty":250,"unit":"g","have":false},{"name":"double cream","plural":"double cream","qty":40,"unit":"cl","have":false},{"name":"icing sugar","plural":"icing sugar","qty":2,"unit":"tbsp","have":false}],"steps":[{"text":"Preheat the oven to 200 °C. Whisk the eggs and sugar until the mixture triples in volume, then fold in the flour.","timer":null},{"text":"Spread on a tray lined with baking paper and bake for 8 min.","timer":{"label":"Oven","min":8}},{"text":"Roll up the warm sponge in a damp tea towel and leave to cool.","timer":null},{"text":"Heat the cream, pour it over the chocolate and leave to cool until the ganache thickens.","timer":null},{"text":"Unroll the sponge, spread with a third of the ganache, roll up and cover with the rest.","timer":null},{"text":"Draw lines with a fork and dust with icing sugar.","timer":null}],"dessert":true},{"title":"Lemon mousse","intro":"A light, tangy lemon mousse to serve in glasses.","minutes":25,"calories":250,"difficulty":"Facile","imageSearch":"lemon mousse","veg":true,"oven":false,"cold":true,"missing":"","origin":"","serves":4,"items":[{"name":"lemon","plural":"lemons","qty":3,"unit":"","have":false},{"name":"egg","plural":"eggs","qty":3,"unit":"","have":false},{"name":"sugar","plural":"sugar","qty":100,"unit":"g","have":false},{"name":"double cream","plural":"double cream","qty":20,"unit":"cl","have":false},{"name":"cornflour","plural":"cornflour","qty":1,"unit":"tbsp","have":false}],"steps":[{"text":"Whisk the yolks, sugar, cornflour, and the juice and zest of the lemons.","timer":null},{"text":"Thicken over a low heat, stirring, then leave to cool.","timer":{"label":"Cooking","min":5}},{"text":"Whip the cream and whisk the whites until stiff.","timer":null},{"text":"Gently fold the whipped cream, then the whites, into the lemon cream.","timer":null},{"text":"Spoon into glasses and chill for 3 h.","timer":null}],"dessert":true},{"title":"Gratin dauphinois","intro":"Soft potatoes cooked slowly in milk and cream, flavoured with garlic.","minutes":80,"calories":420,"difficulty":"Facile","imageSearch":"potato gratin dauphinois","veg":true,"oven":true,"cold":false,"missing":"","origin":"Dauphiné speciality","serves":4,"items":[{"name":"potato","plural":"potatoes","qty":1200,"unit":"g","have":false},{"name":"milk","plural":"milk","qty":50,"unit":"cl","have":false},{"name":"single cream","plural":"single cream","qty":30,"unit":"cl","have":false},{"name":"garlic","plural":"garlic","qty":2,"unit":"clove","have":false},{"name":"butter","plural":"butter","qty":20,"unit":"g","have":false},{"name":"nutmeg","plural":"nutmeg","qty":null,"unit":"","have":false},{"name":"salt","plural":"salt","qty":null,"unit":"","have":false},{"name":"pepper","plural":"pepper","qty":null,"unit":"","have":false}],"steps":[{"text":"Preheat the oven to 160 °C. Peel the potatoes and cut them into thin slices, without washing them.","timer":null},{"text":"Heat the milk, cream and crushed garlic with salt, pepper and nutmeg. Add the potatoes and simmer for 10 min, stirring.","timer":{"label":"Simmer","min":10}},{"text":"Butter a gratin dish and pour everything in.","timer":null},{"text":"Bake for 1 h, until the top is golden and a knife slides in easily.","timer":{"label":"Oven","min":60}}],"kids":true},{"title":"Chocolate profiteroles","intro":"Choux buns filled with vanilla ice cream, covered with hot chocolate sauce.","minutes":75,"calories":450,"difficulty":"Difficile","imageSearch":"profiteroles chocolate sauce","veg":true,"oven":true,"cold":false,"missing":"","origin":"French dessert","serves":4,"items":[{"name":"flour","plural":"flour","qty":75,"unit":"g","have":false},{"name":"butter","plural":"butter","qty":60,"unit":"g","have":false},{"name":"egg","plural":"eggs","qty":2,"unit":"","have":false},{"name":"vanilla ice cream","plural":"vanilla ice cream","qty":50,"unit":"cl","have":false},{"name":"dark chocolate","plural":"dark chocolate","qty":150,"unit":"g","have":false},{"name":"liquid cream","plural":"liquid cream","qty":15,"unit":"cl","have":false},{"name":"salt","plural":"salt","qty":null,"unit":"","have":false}],"steps":[{"text":"Preheat the oven to 200 °C. Bring 12 cl of water, the butter and a pinch of salt to the boil.","timer":null},{"text":"Tip in the flour all at once and stir until the dough comes away from the pan.","timer":null},{"text":"Off the heat, beat in the eggs one by one.","timer":null},{"text":"Pipe small mounds on a baking tray and bake for 25 min without opening the oven.","timer":{"label":"Oven","min":25}},{"text":"Melt the chocolate in the hot cream.","timer":null},{"text":"Cut the cold buns open, fill them with ice cream and cover with the hot sauce.","timer":null}],"dessert":true,"makes":{"n":20,"one":"choux bun","many":"choux buns"}},{"title":"Salmon and cream cheese bagels","intro":"The New York bagel with cream cheese, smoked salmon, red onion and dill.","minutes":10,"calories":420,"difficulty":"Facile","imageSearch":"salmon cream cheese bagel","veg":false,"oven":false,"cold":true,"missing":"","origin":"New York recipe","serves":4,"items":[{"name":"bagel","plural":"bagels","qty":4,"unit":"","have":false},{"name":"cream cheese","plural":"cream cheese","qty":150,"unit":"g","have":false},{"name":"smoked salmon","plural":"smoked salmon","qty":4,"unit":"slices","have":false},{"name":"red onion","plural":"red onions","qty":0.5,"unit":"","have":false},{"name":"dill","plural":"dill","qty":null,"unit":"","have":false},{"name":"lemon","plural":"lemons","qty":0.5,"unit":"","have":false}],"steps":[{"text":"Cut the bagels in half and toast them.","timer":null},{"text":"Spread with cream cheese.","timer":null},{"text":"Add the salmon, sliced onion and dill.","timer":null},{"text":"Squeeze over a little lemon juice and close up.","timer":null}],"makes":{"n":4,"one":"bagel","many":"bagels"}},{"title":"Berry pavlova","intro":"A meringue that is crisp outside and soft inside, with whipped cream and berries.","minutes":150,"calories":300,"difficulty":"Moyen","imageSearch":"berry pavlova","veg":true,"oven":true,"cold":false,"missing":"","origin":"Australian dessert","serves":4,"items":[{"name":"egg white","plural":"egg whites","qty":4,"unit":"","have":false},{"name":"sugar","plural":"sugar","qty":200,"unit":"g","have":false},{"name":"cornflour","plural":"cornflour","qty":1,"unit":"tsp","have":false},{"name":"white vinegar","plural":"white vinegar","qty":1,"unit":"tsp","have":false},{"name":"whole liquid cream","plural":"whole liquid cream","qty":30,"unit":"cl","have":false},{"name":"mixed berries","plural":"mixed berries","qty":300,"unit":"g","have":false}],"steps":[{"text":"Preheat the oven to 120 °C.","timer":null},{"text":"Whisk the whites to stiff peaks, then add the sugar little by little until you have a glossy meringue.","timer":null},{"text":"Add the cornflour and vinegar, and shape into a big disc on a baking tray.","timer":null},{"text":"Bake for 1 h 30, then leave to cool in the switched-off oven.","timer":{"label":"Oven","min":90}},{"text":"Whip the cream, spread it over the meringue and top with the berries.","timer":null}],"dessert":true},{"title":"Carrot cake","intro":"The soft cake with carrots and spices, with its cream cheese frosting.","minutes":80,"calories":450,"difficulty":"Moyen","imageSearch":"carrot cake frosting","veg":true,"oven":true,"cold":false,"missing":"","origin":"Anglo-Saxon recipe","serves":4,"items":[{"name":"carrot","plural":"carrots","qty":3,"unit":"","have":false},{"name":"egg","plural":"eggs","qty":3,"unit":"","have":false},{"name":"brown sugar","plural":"brown sugar","qty":150,"unit":"g","have":false},{"name":"sunflower oil","plural":"sunflower oil","qty":15,"unit":"cl","have":false},{"name":"flour","plural":"flour","qty":250,"unit":"g","have":false},{"name":"baking powder","plural":"baking powder","qty":2,"unit":"tsp","have":false},{"name":"cinnamon","plural":"cinnamon","qty":2,"unit":"tsp","have":false},{"name":"cream cheese","plural":"cream cheese","qty":200,"unit":"g","have":false},{"name":"icing sugar","plural":"icing sugar","qty":60,"unit":"g","have":false}],"steps":[{"text":"Preheat the oven to 180 °C. Finely grate the carrots.","timer":null},{"text":"Whisk the eggs, brown sugar and oil.","timer":null},{"text":"Add the flour, baking powder and cinnamon, then the carrots.","timer":null},{"text":"Pour into a buttered tin and bake for 45 min. Leave to cool.","timer":{"label":"Oven","min":45}},{"text":"Whisk the cream cheese and icing sugar, and spread this frosting over the cake.","timer":null}],"dessert":true},{"title":"Strawberry charlotte","intro":"Sponge fingers around a light strawberry mousse.","minutes":40,"calories":350,"difficulty":"Moyen","imageSearch":"strawberry charlotte","veg":true,"oven":false,"cold":true,"missing":"","origin":"","serves":4,"items":[{"name":"sponge finger","plural":"sponge fingers","qty":24,"unit":"","have":false},{"name":"strawberry","plural":"strawberries","qty":500,"unit":"g","have":false},{"name":"whole liquid cream","plural":"whole liquid cream","qty":30,"unit":"cl","have":false},{"name":"fromage blanc","plural":"fromage blanc","qty":250,"unit":"g","have":false},{"name":"sugar","plural":"sugar","qty":80,"unit":"g","have":false},{"name":"gelatine","plural":"gelatine","qty":4,"unit":"leaves","have":false}],"steps":[{"text":"Soften the gelatine in cold water. Blend half the strawberries with the sugar.","timer":null},{"text":"Warm a little of this coulis and melt the gelatine in it, then mix with the rest.","timer":null},{"text":"Whip the cream and fold it into the fromage blanc and the coulis.","timer":null},{"text":"Quickly dip the sponge fingers in sugar water and line a tin.","timer":null},{"text":"Layer the mousse and chopped strawberries, then cover with sponge fingers.","timer":null},{"text":"Leave to set in the fridge for 6 h before turning out.","timer":null}],"dessert":true},{"title":"New York cheesecake","intro":"The creamy cheesecake on a biscuit base, baked gently in the oven.","minutes":90,"calories":480,"difficulty":"Moyen","imageSearch":"new york cheesecake","veg":true,"oven":true,"cold":false,"missing":"","origin":"New York recipe","serves":4,"items":[{"name":"plain biscuit","plural":"plain biscuits","qty":200,"unit":"g","have":false},{"name":"melted butter","plural":"melted butter","qty":80,"unit":"g","have":false},{"name":"cream cheese","plural":"cream cheese","qty":600,"unit":"g","have":false},{"name":"sugar","plural":"sugar","qty":150,"unit":"g","have":false},{"name":"egg","plural":"eggs","qty":3,"unit":"","have":false},{"name":"crème fraîche","plural":"crème fraîche","qty":20,"unit":"cl","have":false},{"name":"lemon","plural":"lemons","qty":1,"unit":"","have":false}],"steps":[{"text":"Preheat the oven to 160 °C. Crush the biscuits and mix them with the melted butter.","timer":null},{"text":"Press this mixture into the bottom of a springform tin.","timer":null},{"text":"Whisk the cream cheese, sugar, cream and lemon zest, then the eggs one by one.","timer":null},{"text":"Pour over the base and bake for 1 h.","timer":{"label":"Oven","min":60}},{"text":"Leave to cool in the oven with the door ajar, then chill for at least 4 h.","timer":null}],"dessert":true},{"title":"Chocolate tart","intro":"A sweet shortcrust base with a rich dark chocolate ganache.","minutes":50,"calories":450,"difficulty":"Moyen","imageSearch":"chocolate tart","veg":true,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"sweet shortcrust pastry","plural":"sweet shortcrust pastries","qty":1,"unit":"","have":false},{"name":"dark chocolate","plural":"dark chocolate","qty":200,"unit":"g","have":false},{"name":"double cream","plural":"double cream","qty":20,"unit":"cl","have":false},{"name":"butter","plural":"butter","qty":30,"unit":"g","have":false},{"name":"egg","plural":"eggs","qty":1,"unit":"","have":false}],"steps":[{"text":"Preheat the oven to 180 °C. Blind bake the pastry for 20 min.","timer":{"label":"Oven","min":20}},{"text":"Heat the cream and pour it over the chopped chocolate.","timer":null},{"text":"Stir, then add the butter and the beaten egg.","timer":null},{"text":"Pour into the pastry case and bake for 10 min at 150 °C.","timer":{"label":"Oven","min":10}},{"text":"Leave to cool for at least 1 h.","timer":null}],"dessert":true},{"title":"Panna cotta with berry coulis","intro":"The wobbly Italian cream, flavoured with vanilla, with a berry coulis.","minutes":20,"calories":330,"difficulty":"Facile","imageSearch":"panna cotta berry coulis","veg":true,"oven":false,"cold":true,"missing":"","origin":"Italian dessert","serves":4,"items":[{"name":"whole liquid cream","plural":"whole liquid cream","qty":50,"unit":"cl","have":false},{"name":"sugar","plural":"sugar","qty":80,"unit":"g","have":false},{"name":"gelatine","plural":"gelatine","qty":3,"unit":"leaves","have":false},{"name":"vanilla pod","plural":"vanilla pods","qty":1,"unit":"","have":false},{"name":"frozen mixed berries","plural":"frozen mixed berries","qty":250,"unit":"g","have":false}],"steps":[{"text":"Soften the gelatine in cold water.","timer":null},{"text":"Heat the cream with 60 g of sugar and the split vanilla pod, without boiling.","timer":{"label":"Cooking","min":5}},{"text":"Take off the heat, add the squeezed gelatine and stir.","timer":null},{"text":"Pour into glasses and leave to set in the fridge for 4 h.","timer":null},{"text":"Blend the berries with the rest of the sugar and pour over just before serving.","timer":null}],"dessert":true},{"title":"No-churn vanilla ice cream","intro":"A creamy vanilla ice cream made with condensed milk, with no machine.","minutes":15,"calories":330,"difficulty":"Facile","imageSearch":"no churn vanilla ice cream","veg":true,"oven":false,"cold":true,"missing":"","origin":"","serves":4,"items":[{"name":"whipping cream","plural":"whipping cream","qty":50,"unit":"cl","have":false},{"name":"condensed milk","plural":"condensed milk","qty":400,"unit":"g","have":false},{"name":"vanilla pod","plural":"vanilla pods","qty":1,"unit":"","have":false}],"steps":[{"text":"Whip the very cold cream until stiff.","timer":null},{"text":"Mix the condensed milk with the vanilla seeds.","timer":null},{"text":"Gently fold in the whipped cream.","timer":null},{"text":"Pour into a tub and freeze for 6 h.","timer":null}],"kids":true,"dessert":true},{"title":"Four cheese pasta","intro":"Pasta covered in a melting cream sauce with gorgonzola, mozzarella, parmesan and Emmental.","minutes":20,"calories":700,"difficulty":"Facile","imageSearch":"four cheese pasta","veg":true,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"pasta","plural":"pasta","qty":400,"unit":"g","have":false},{"name":"gorgonzola","plural":"gorgonzola","qty":100,"unit":"g","have":false},{"name":"mozzarella","plural":"mozzarella","qty":1,"unit":"","have":false},{"name":"parmesan","plural":"parmesan","qty":40,"unit":"g","have":false},{"name":"grated emmental","plural":"grated emmental","qty":60,"unit":"g","have":false},{"name":"single cream","plural":"single cream","qty":20,"unit":"cl","have":false}],"steps":[{"text":"Cook the pasta.","timer":{"label":"Cooking","min":10}},{"text":"Heat the cream over a low heat.","timer":null},{"text":"Add the gorgonzola, the diced mozzarella, the Emmental and the parmesan, and stir until everything has melted.","timer":null},{"text":"Mix with the pasta and add pepper.","timer":null}],"kids":true},{"title":"Pears belle Hélène","intro":"Pears poached in vanilla syrup, covered with hot chocolate.","minutes":40,"calories":330,"difficulty":"Facile","imageSearch":"poire belle helene","veg":true,"oven":false,"cold":true,"missing":"","origin":"French dessert","serves":4,"items":[{"name":"pear","plural":"pears","qty":4,"unit":"","have":false},{"name":"sugar","plural":"sugar","qty":150,"unit":"g","have":false},{"name":"vanilla pod","plural":"vanilla pods","qty":1,"unit":"","have":false},{"name":"dark chocolate","plural":"dark chocolate","qty":150,"unit":"g","have":false},{"name":"liquid cream","plural":"liquid cream","qty":15,"unit":"cl","have":false},{"name":"vanilla ice cream","plural":"vanilla ice cream","qty":50,"unit":"cl","have":false}],"steps":[{"text":"Bring 1 litre of water to the boil with the sugar and the split vanilla pod.","timer":null},{"text":"Peel the pears, leaving the stalk on, and poach them in the syrup for 20 min.","timer":{"label":"Cooking","min":20}},{"text":"Leave them to cool in the syrup.","timer":null},{"text":"Melt the chocolate in the hot cream.","timer":null},{"text":"Serve each pear with a scoop of ice cream and the chocolate sauce.","timer":null}],"dessert":true},{"title":"Asparagus with mousseline sauce","intro":"Perfectly cooked white asparagus with a light mousseline sauce.","minutes":30,"calories":250,"difficulty":"Moyen","imageSearch":"white asparagus hollandaise","veg":true,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"white asparagus","plural":"white asparagus","qty":1000,"unit":"g","have":false},{"name":"egg","plural":"eggs","qty":2,"unit":"","have":false},{"name":"butter","plural":"butter","qty":80,"unit":"g","have":false},{"name":"single cream","plural":"single cream","qty":10,"unit":"cl","have":false},{"name":"lemon","plural":"lemons","qty":0.5,"unit":"","have":false}],"steps":[{"text":"Peel the asparagus and boil it for 15 min in salted water.","timer":{"label":"Cooking","min":15}},{"text":"Whisk the egg yolks with 2 tbsp of water over a pan of simmering water until thick.","timer":null},{"text":"Add the melted butter little by little, then the lemon juice.","timer":null},{"text":"Whip the cream and fold it into the sauce.","timer":null},{"text":"Serve the warm asparagus with the sauce.","timer":null}]},{"title":"Cheesy gratin dauphinois","intro":"The classic, with a golden, stretchy comté topping.","minutes":80,"calories":520,"difficulty":"Facile","imageSearch":"cheese potato gratin","veg":true,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"potato","plural":"potatoes","qty":1200,"unit":"g","have":false},{"name":"milk","plural":"milk","qty":50,"unit":"cl","have":false},{"name":"single cream",